CREATE TABLE IF NOT EXISTS academic_classes (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, section VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS academic_subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, code VARCHAR(30) UNIQUE);
CREATE TABLE IF NOT EXISTS academic_teachers (id INT AUTO_INCREMENT PRIMARY KEY, employee_id VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(150), phone VARCHAR(30), qualification VARCHAR(150), designation VARCHAR(80), subject_specialization VARCHAR(150), joining_date DATE, address VARCHAR(255), photo_url VARCHAR(255), status VARCHAR(30) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS academic_students (id INT AUTO_INCREMENT PRIMARY KEY, admission_no VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, class_id INT NOT NULL, roll_no VARCHAR(20), FOREIGN KEY (class_id) REFERENCES academic_classes(id));
CREATE TABLE IF NOT EXISTS academic_teacher_class_allocation (id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, class_id INT NOT NULL, subject_id INT NOT NULL, is_class_teacher TINYINT(1) DEFAULT 0, academic_year VARCHAR(20) DEFAULT '2026-2027', FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id), FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (subject_id) REFERENCES academic_subjects(id));
CREATE TABLE IF NOT EXISTS academic_timetable (id INT AUTO_INCREMENT PRIMARY KEY, class_id INT NOT NULL, subject_id INT NOT NULL, teacher_id INT NOT NULL, day_of_week VARCHAR(20) NOT NULL, period_no INT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, room VARCHAR(80), FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (subject_id) REFERENCES academic_subjects(id), FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_homework (id INT AUTO_INCREMENT PRIMARY KEY, class_id INT NOT NULL, subject_id INT NOT NULL, teacher_id INT NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, assigned_date DATE DEFAULT (CURRENT_DATE), due_date DATE, attachment_url VARCHAR(255), status VARCHAR(30) DEFAULT 'Published', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (subject_id) REFERENCES academic_subjects(id), FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_syllabus (id INT AUTO_INCREMENT PRIMARY KEY, class_id INT NOT NULL, subject_id INT NOT NULL, teacher_id INT NOT NULL, unit_title VARCHAR(200) NOT NULL, topics TEXT, planned_start_date DATE, planned_end_date DATE, completion_status VARCHAR(30) DEFAULT 'Not Started', completion_percent INT DEFAULT 0, FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (subject_id) REFERENCES academic_subjects(id), FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_calendar (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, event_type VARCHAR(50), start_date DATE NOT NULL, end_date DATE, description TEXT);
CREATE TABLE IF NOT EXISTS academic_student_attendance (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, class_id INT NOT NULL, attendance_date DATE DEFAULT (CURRENT_DATE), status VARCHAR(30) NOT NULL, marked_by INT, remarks TEXT, is_corrected TINYINT(1) DEFAULT 0, corrected_at DATETIME, corrected_by INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_student_attendance (student_id, attendance_date), FOREIGN KEY (student_id) REFERENCES academic_students(id), FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (marked_by) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_staff_attendance (id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, attendance_date DATE DEFAULT (CURRENT_DATE), status VARCHAR(30) NOT NULL, check_in TIME, check_out TIME, remarks TEXT, UNIQUE KEY uq_staff_attendance (teacher_id, attendance_date), FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_leave_requests (id INT AUTO_INCREMENT PRIMARY KEY, applicant_type VARCHAR(30) NOT NULL, teacher_id INT, student_id INT, leave_type VARCHAR(30), start_date DATE NOT NULL, end_date DATE NOT NULL, reason TEXT, status VARCHAR(30) DEFAULT 'Pending', applied_on TIMESTAMP DEFAULT CURRENT_TIMESTAMP, approved_by VARCHAR(150), FOREIGN KEY (teacher_id) REFERENCES academic_teachers(id), FOREIGN KEY (student_id) REFERENCES academic_students(id));
CREATE TABLE IF NOT EXISTS academic_exams (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, exam_type VARCHAR(50), class_id INT NOT NULL, subject_id INT NOT NULL, exam_date DATE NOT NULL, start_time TIME, end_time TIME, max_marks INT DEFAULT 100, pass_marks INT DEFAULT 33, academic_year VARCHAR(20) DEFAULT '2026-2027', FOREIGN KEY (class_id) REFERENCES academic_classes(id), FOREIGN KEY (subject_id) REFERENCES academic_subjects(id));
CREATE TABLE IF NOT EXISTS academic_marks (id INT AUTO_INCREMENT PRIMARY KEY, exam_id INT NOT NULL, student_id INT NOT NULL, marks_obtained DECIMAL(10,2) NOT NULL, grade VARCHAR(10), remarks TEXT, entered_by INT, entered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_marks (exam_id, student_id), FOREIGN KEY (exam_id) REFERENCES academic_exams(id), FOREIGN KEY (student_id) REFERENCES academic_students(id), FOREIGN KEY (entered_by) REFERENCES academic_teachers(id));
CREATE TABLE IF NOT EXISTS academic_grade_scale (id INT AUTO_INCREMENT PRIMARY KEY, grade VARCHAR(10) NOT NULL, min_percent DECIMAL(5,2) NOT NULL, max_percent DECIMAL(5,2) NOT NULL, remarks VARCHAR(150));
